/// <summary>
/// PaffH 28.12.23
/// </summary>
/// <param name = "kCS_KBVBuildingProjectID">KCS_KBVBuildingProjectID</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDX_KBV2RicoKalkMap</returns>
public static NDX_KBV2RicoKalkMap find(KCS_KBVBuildingProjectID kCS_KBVBuildingProjectID,
    boolean _forUpdate = false)
{
    NDX_KBV2RicoKalkMap nDX_KBV2RicoKalkMap;

    nDX_KBV2RicoKalkMap.selectForUpdate(_forUpdate);

    if(kCS_KBVBuildingProjectID)
    {
        select firstonly    nDX_KBV2RicoKalkMap
        where           nDX_KBV2RicoKalkMap.KBVBuildingProjectID == kCS_KBVBuildingProjectID;
    }

    return nDX_KBV2RicoKalkMap;
}

/// <summary>
/// PaffH 28.12.23
/// </summary>
/// <param name = "ricoKalkBVNr">NDXRicoKalkBVNr</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDX_KBV2RicoKalkMap</returns>
public static NDX_KBV2RicoKalkMap findRicoKalkBVNr(NDXRicoKalkBVNr ricoKalkBVNr,
                                               boolean          _forUpdate = false)
{
    NDX_KBV2RicoKalkMap nDX_KBV2RicoKalkMap;
    ;

    nDX_KBV2RicoKalkMap.selectForUpdate(_forUpdate);

    if(ricoKalkBVNr)
    {
        select firstonly    nDX_KBV2RicoKalkMap
        where           nDX_KBV2RicoKalkMap.RicoKalkBVNr == ricoKalkBVNr;
    }

    return nDX_KBV2RicoKalkMap;
}

/// <summary>
/// PaffH 28.12.23
/// </summary>
/// <param name = "KbvBuildingProjectId">KCS_KBVBuildingProjectID</param>
/// <returns>boolean</returns>
static boolean exist(KCS_KBVBuildingProjectID    KbvBuildingProjectId)
{
    if (!KbvBuildingProjectId)
    {
        return false;
    }

    return (select firstonly RecId from NDX_KBV2RicoKalkMap
        where NDX_KBV2RicoKalkMap.KBVBuildingProjectID == KbvBuildingProjectId).RecId != 0;
}

/// <summary>
/// PaffH 28.12.23
/// </summary>
/// <param name = "kCS_KBVBuildingProjectID">KCS_KBVBuildingProjectID</param>
/// <returns>NDXRicoKalkBVNr</returns>
public static NDXRicoKalkBVNr get_BVNrRicoKalk(KCS_KBVBuildingProjectID kCS_KBVBuildingProjectID)
{
    NDX_KBV2RicoKalkMap nDX_KBV2RicoKalkMap;

    if(kCS_KBVBuildingProjectID)
    {
        select firstonly nDX_KBV2RicoKalkMap
            where nDX_KBV2RicoKalkMap.KBVBuildingProjectID == kCS_KBVBuildingProjectID;
    }

    return nDX_KBV2RicoKalkMap.RicoKalkBVNr;
}
